    int minCostClimbingStairs(vector<int>& cost) {
        int dp = 0, dp1 = 0, dp2 = 0;
        for(int i = 2; i <= cost.size(); i++){
            int one = dp1 + cost[i-1];
            int two = dp2 + cost[i-2];
            dp = min(one, two);
            dp2 = dp1;
            dp1 = dp;
        }
        return dp1;
    }
