public:
    bool isPossible(vector<int>& v) {
        unordered_map<int, int> mp1, mp2;
        for(auto x: v)
            mp1[x]++;

        for(auto x: v){
            if(mp1[x] == 0)  continue;
            mp1[x]--;

            if(mp2[x-1] > 0){
                mp2[x-1]--;
                mp2[x]++;
            }
            else if(mp1[x+1] > 0 and mp1[x+2] > 0){
                mp1[x+1]--;
                mp1[x+2]--;
                mp2[x+2]++;
            }
            else
                return false;
        }
        return true;
    }
};, language: C++, approach: Greedy with Hash Maps})

(:Solution {code: class Solution:
    def isPossible(self, v: List[int]) -> bool:
        mp1 = collections.Counter(v)
        mp2 = collections.Counter()

        for x in v:
            if not mp1[x]:  continue
            mp1[x] -= 1

            if mp2[x-1] > 0:
                mp2[x-1] -= 1
                mp2[x] += 1
            elif mp1[x+1] and mp1[x+2]:
                mp1[x+1] -= 1
                mp1[x+2] -= 1
                mp2[x+2] += 1
            else:
                return False
        return True, language: Python, approach: Greedy with Hash Maps})

(:Solution {code: class Solution {
public:
    int minSetSize(vector<int>& arr) {
        int ans = 0, c = 0;
        unordered_map<int, int> mp;
        for(auto x: arr)
            mp[x]++;

        vector<int> v;
        for(auto it: mp)
            v.push_back(it.second);

        sort(v.rbegin(), v.rend()); // Sort descending
        for(int i = 0; i < v.size(); i++){
            ans += v[i];
            c++;
            if(ans >= arr.size()/2)
                return c;
        }
        return c;
    }
};, language: C++ (Sort), approach: Greedy with Frequency Counting})

(:Solution {code: class Solution {
public:
    int minSetSize(vector<int>& arr) {
        int x = 0, ans = 0;
        unordered_map<int, int> mp;
        for(auto i: arr)
            mp[i]++;

        priority_queue<int> pq;
        for(auto i: mp)
            pq.push(i.second);

        while(x < arr.size()/2){
            x += pq.top();
            pq.pop();
            ans++;
        }
        return ans;
    }
};, language: C++ (Priority Queue), approach: Greedy with Frequency Counting})

(:Solution {code: class Solution {
public:
    vector<int> ans;
    void solve(int len, int &k, int num, int digit){
        if(len == 0){
            ans.push_back(num);
            return;
        }
        int next_digit_add = digit + k;
        int next_digit_sub = digit - k;

        if(next_digit_add >= 0 && next_digit_add < 10){
            solve(len-1, k, num*10 + next_digit_add, next_digit_add);
        }

        // Avoid double counting if k is 0
        if(k != 0 && next_digit_sub >= 0 && next_digit_sub < 10){
            solve(len-1, k, num*10 + next_digit_sub, next_digit_sub);
        }
    }

    vector<int> numsSameConsecDiff(int n, int k) {
        for(int i = 1; i <= 9; i++)      
            solve(n-1, k, i, i);
        return ans;
    }
};, language: C++, approach: Backtracking (DFS)})

(:Solution {code: class Solution {
public:
    bool canVisitAllRooms(vector<vector<int>>& rooms) {
        int n = rooms.size();
        vector<bool> vis(n, false);
        queue<int> q;
        q.push(0);
        vis[0] = true;

        while(!q.empty()){
            int room = q.front();
            q.pop();
            for(auto it: rooms[room]){
                if(!vis[it]){
                    q.push(it);
                    vis[it] = true;
                }
            }
        }
        for(auto it: vis)
            if(!it)
                return false;
        return true;
    }
};, language: C++, approach: Graph Traversal (BFS)})

