    stack<long long> s;
    for(auto& t : tokens){
            if(t == "+" || t == "-" || t == "*" || t == "/") {
            long long op1 = s.top(); s.pop();
            long long op2 = s.top(); s.pop();
            if(t == "+") op1 = op2 + op1; 
            if(t == "-") op1 = op2 - op1;
            if(t == "/") op1 = op2 / op1;
            if(t == "*") op1 = op2 * op1;   
                s.push(op1);
        }
