(:Solution {code: class Solution {
public:
    int maxProfit(int k, vector<int>& prices) {
        if(k == 0)  return 0;
        vector<vector<int>> dp(k+1, vector<int>(2));

        for(int i = 0; i <= k; i++){
            dp[i][0] = INT_MAX; // cost to buy
            dp[i][1] = 0;       // profit to sell
        }

        for(auto &p: prices){
            for(int i = 1; i <= k; i++){
                dp[i][0] = min(dp[i][0], p - dp[i-1][1]);
                dp[i][1] = max(dp[i][1], p - dp[i][0]);
            }
        }
        return dp[k][1];
    }
};, language: C++, approach: Dynamic Programming})

(:Solution {code: class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        if k == 0: return 0
        # dp[i][0] = cost to buy, dp[i][1] = profit to sell for transaction i
        dp = [[float('inf'), 0] for _ in range(k + 1)]

        for p in prices:
            for i in range(1, k + 1):
                dp[i][0] = min(dp[i][0], p - dp[i-1][1])
                dp[i][1] = max(dp[i][1], p - dp[i][0])

        return dp[k][1], language: Python, approach: Dynamic Programming})

(:Solution {code: class Solution {
public:
    int kInversePairs(int n, int k) {
        int dp[2][1001] = {};
        dp[0][0] = 1;
        int mod = 1e9 + 7;
        for(int i = 1; i <= n; i++) {
            int current = i % 2;
            int prev = (i - 1) % 2;
            dp[current][0] = 1;
            for(int j = 1; j <= k; j++) {
                dp[current][j] = (dp[prev][j] + dp[current][j-1]) % mod;
                if(j >= i) {
                    dp[current][j] = (dp[current][j] - dp[prev][j-i] + mod) % mod;
                }
            }
        }
        return dp[n%2][k];
    }
};, language: C++, approach: Optimized Dynamic Programming})

(:Solution {code: class Solution {
public:
    ListNode *mergeTwoLists(ListNode* l1, ListNode* l2) {
        if (NULL == l1) return l2;
        else if (NULL == l2) return l1;

        if (l1->val <= l2->val) {
            l1->next = mergeTwoLists(l1->next, l2);
            return l1;
        }

        else {
            l2->next = mergeTwoLists(l1, l2->next);
            return l2;
        }
    }

    ListNode *mergeKLists(vector<ListNode *> &lists) {
        if (lists.empty()) return NULL;
        int len = lists.size();

        while (len > 1) {
            for (int i = 0; i < len / 2; ++i) {
                lists[i] = mergeTwoLists(lists[i], lists[len - 1 - i]);
            }

            len = (len + 1) / 2;
        }

        return lists.front();
    }
};, language: C++, approach: Divide and Conquer (Merge in Pairs)})

(:Solution {code: class Solution {
public:
    string minWindow(string s, string t) {
        vector<int> mp(128, 0);
        for(auto c: t){
            mp[c]++;
        }
        int low = 0, high = 0, m = s.size(), n = t.size(), minStart = 0, minLen = INT_MAX;

        while(high < m){
            if(mp[s[high]] > 0)
                n--;
            mp[s[high]]--;
            high++;

            while(n == 0){
                if(high - low < minLen){
                    minStart = low;
                    minLen = high - low;
                }
                mp[s[low]]++;
                if(mp[s[low]] > 0)
                    n++;
                low++;
            }
        }
        if(minLen != INT_MAX)
            return s.substr(minStart, minLen);
        return "";
    }
};, language: C++, approach: Sliding Window})

(:Solution {code: class Solution {
public:
    int longestValidParentheses(string s) {
        stack<int> st;
        st.push(-1);
        int ans = 0;

        for(int i = 0; i < s.size(); i++){
            if(s[i] == '('){
                st.push(i);
            }
            else {
                st.pop();
                if (st.empty()) {
                    st.push(i);
                }
                else {
                    ans = max(ans, i - st.top());
                }
            }
        }
        return ans;
    }
};, language: C++, approach: Stack with Index Tracking})

(:Solution {code: class Solution:
    def longestValidParentheses(self, s: str) -> int:
        st = [-1]
        ans = 0

        for i, char in enumerate(s):
            if char == '(':
                st.append(i)
            else:
                st.pop()
                if not st:
                    st.append(i)
                else:
                    ans = max(ans, i - st[-1])

        return ans, language: Python, approach: Stack with Index Tracking})

